// ---------------------------------------------------------------------------
// Text Normalization Layer  -  deterministic JS twin of normalize.py.
// NO LLM. NO network. NO randomness. Idempotent. Standard n8n Code node.
// Keep character tables byte-identical to the Python script.
// ---------------------------------------------------------------------------
const INPUT_FIELD  = 'text';   // <- field on each item to read
const OUTPUT_FIELD = 'text';   // <- field to write the cleaned text back to
const MODE         = 'content-safe'; // 'content-safe' (publish) | 'aggressive' (NLP/search key)
const COLLAPSE_NEWLINES = true;
// Names / non-translatable words whose accents must survive even in aggressive
// mode (respect-translation-accents rule). Load from SITE_CONFIG in production.
const PROTECT = ['Galápagos','José','Ñandú','Quito','Cotopaxi'];

// Zero-width / invisible / bidi-format chars -> DELETED.
const ZERO_WIDTH = /[\u200b\u200c\u200d\u2060\ufeff\u180e\u00ad\u200e\u200f\u202a\u202b\u202c\u202d\u202e\u2061\u2062\u2063\u2064]/g;
// Unicode/typographic spaces (incl. non-breaking) -> single ASCII space.
const UNICODE_SPACES = /[\u00a0\u2007\u202f\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2008\u2009\u200a\u205f\u3000\u1680\t\v\f]/g;
// Control chars (keep \n).
const CONTROLS = /[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g;
const PUNCT = [
  [/[\u2018\u2019\u201a\u201b\u2032]/g, "'"],
  [/[\u201c\u201d\u201e\u201f\u2033]/g, '"'],
  [/[\u2013\u2014\u2015\u2212\u2010\u2011]/g, '-'],
  [/\u2026/g, '...'],
  [/[\u00ab\u00bb]/g, '"'],
  [/\u2044/g, '/']
];

function normalize(input) {
  if (input === null || input === undefined) return '';
  let text = String(input);
  // 1. Unicode NFKC.
  text = text.normalize('NFKC');
  // 2. Zero-width / invisible -> gone.
  text = text.replace(ZERO_WIDTH, '');
  // 3. Controls -> gone.
  text = text.replace(CONTROLS, '');
  // 4. Line separators -> \n; unicode spaces -> ' '.
  text = text.replace(/\r\n?|[\u2028\u2029]/g, '\n').replace(UNICODE_SPACES, ' ');

  if (MODE === 'aggressive') {
    const fold = (s) => s.normalize('NFKD').replace(/[\u0300-\u036f]/g, '');
    let folded = fold(text);
    if (PROTECT && PROTECT.length) {
      // Restore accents only for protected names/terms (accent- & case-insensitive).
      const ph = {};
      PROTECT.filter(Boolean).forEach((term, i) => {
        const token = '\u0000P' + i + '\u0000';
        const re = new RegExp('(?<!\\w)' + fold(term).replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(?!\\w)', 'gi');
        folded = folded.replace(re, token);
        ph[token] = term.toLowerCase();
      });
      let out = folded.replace(/[^a-zA-Z0-9\s\u0000]/g, '');
      for (const t in ph) out = out.split(t).join(ph[t]);
      return out.replace(/\s+/g, ' ').trim().toLowerCase();
    }
    return folded.replace(/[^a-zA-Z0-9\s]/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
  }

  // 5. Smart punctuation -> ASCII.
  for (const [re, rep] of PUNCT) text = text.replace(re, rep);
  // 6. Whitespace standardization (structure-preserving).
  text = text.replace(/ {2,}/g, ' ').replace(/[ \t]+(?=\n)/g, '');
  text = COLLAPSE_NEWLINES ? text.replace(/\n{3,}/g, '\n\n')
                          : text.replace(/\n/g, ' ').replace(/ {2,}/g, ' ');
  return text.trim();
}

function report(original, cleaned) {
  const count = (s, re) => (s.match(re) || []).length;
  return {
    changed: original !== cleaned,
    original_length: original.length,
    cleaned_length: cleaned.length,
    zero_width_removed: count(original, ZERO_WIDTH),
    non_breaking_spaces_removed: count(original, /\u00a0/g),
    unicode_spaces_normalized: count(original, UNICODE_SPACES),
    control_chars_removed: count(original, CONTROLS),
    mode: MODE
  };
}

return items.map((item) => {
  const original = String(item.json[INPUT_FIELD] ?? '');
  const cleaned = normalize(original);
  return { json: { ...item.json, [OUTPUT_FIELD]: cleaned, _normalization: report(original, cleaned) } };
});
